const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sections=['Crushing','Flotation','Filter Press'];
const initial={faults:[{id:'FLT-1003',title:'Conveyor belt misalignment',section:'Crushing',priority:'High',team:'Mechanical',status:'Open'},{id:'FLT-1002',title:'Cell motor vibration',section:'Flotation',priority:'Critical',team:'Electrical',status:'In progress'},{id:'FLT-1001',title:'Hydraulic pressure fluctuation',section:'Filter Press',priority:'Medium',team:'Mechanical',status:'Open'}],workers:[{id:'EMP-001',name:'Sample operator A',section:'Crushing',role:'Operator'},{id:'EMP-002',name:'Sample supervisor B',section:'Flotation',role:'Supervisor'},{id:'EMP-003',name:'Sample operator C',section:'Filter Press',role:'Operator'}],logs:[],reports:[],training:[{id:'TR-001',title:'Plant induction',section:'All sections',status:'Pending'},{id:'TR-002',title:'Isolation and lockout awareness',section:'Crushing',status:'Pending'},{id:'TR-003',title:'Chemical handling awareness',section:'Flotation',status:'Pending'}]};
let data;try{data=JSON.parse(localStorage.getItem('mineflow-pilot-v1'))||structuredClone(initial)}catch{data=structuredClone(initial)}let page='Overview';
const pages=['Overview','Fault reports','Workers','Shift logs','Anonymous reports','Training','Sections'];const icons=['◫','⚑','♙','≡','◇','▤','▦'];
const save=()=>{localStorage.setItem('mineflow-pilot-v1',JSON.stringify(data));render();toast('Saved in this browser')};function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function table(headers,rows){return rows.length?`<table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>`:'<div class="empty">No records yet. Add the first record to get started.</div>'}const badge=s=>`<span class="badge ${esc(s)}">${esc(s)}</span>`;
function faultRows(items,actions=true){return items.map(f=>`<tr><td><span class="muted">${esc(f.id)}</span><br><b>${esc(f.title)}</b></td><td>${esc(f.section)}</td><td>${badge(f.priority)}</td><td>${esc(f.team)}</td><td>${actions?`<select aria-label="Status for ${esc(f.id)}" data-fault="${esc(f.id)}">${['Open','In progress','Resolved'].map(s=>`<option ${s===f.status?'selected':''}>${s}</option>`).join('')}</select>`:badge(f.status)}</td></tr>`)}
function render(){document.querySelector('nav').innerHTML=pages.map((p,i)=>`<button class="${p===page?'active':''}" data-page="${p}">${icons[i]} &nbsp; ${p}</button>`).join('');$('#title').textContent=page==='Overview'?'Operations overview':page;$('#subtitle').textContent=({Overview:'A clearer view of your people, plant, and priorities.','Fault reports':'Capture issues. Assign support. Track the resolution.',Workers:'Your Mineral Processing team, in one place.','Shift logs':'Keep the next shift informed.','Anonymous reports':'Explore a reporting workflow without entering identifying details.',Training:'Plan learning and track completion.',Sections:'Three sections. One connected operation.'})[page];$('#add').hidden=['Sections'].includes(page);$('#add').textContent=({'Overview':'+ Report a fault','Fault reports':'+ Report a fault',Workers:'+ Add worker','Shift logs':'+ Add shift log','Anonymous reports':'+ Submit report',Training:'+ Add training'})[page]||'';
let html='';if(page==='Overview'){const open=data.faults.filter(f=>f.status!=='Resolved');html=`<div class="stats">${[['Open faults',open.length,'Across all processing sections'],['Critical issues',open.filter(f=>f.priority==='Critical').length,'Requires supervisor review'],['Registered workers',data.workers.length,'Sample workforce directory'],['Training complete',data.training.filter(t=>t.status==='Complete').length+'/'+data.training.length,'Pilot learning activities']].map(s=>`<div class="stat"><label>${s[0]}</label><strong>${s[1]}</strong><small>${s[2]}</small></div>`).join('')}</div><div class="grid"><div class="panel"><h2>Faults requiring attention</h2>${table(['Issue','Section','Priority','Support team','Status'],faultRows(open,false))}</div><div class="panel"><h2>Shift readiness</h2><p>Good handovers start with clear records.</p><div class="row"><span>Shift logs captured</span><b>${data.logs.length}</b></div><div class="row"><span>Support departments</span><b>3</b></div><p class="muted">Electrical · Mechanical · Safety</p><button data-page="Shift logs" class="quiet">Open shift log →</button></div></div>${sectionCards()}`}
if(page==='Fault reports')html=`<div class="panel"><div class="toolbar"><input id="search" placeholder="Search faults or equipment…" aria-label="Search faults"><select id="filter" aria-label="Section filter"><option>All sections</option>${sections.map(s=>`<option>${s}</option>`).join('')}</select></div><div id="fault-table"></div></div>`;
if(page==='Workers')html=`<div class="panel">${table(['Employee ID','Name','Section','Role'],data.workers.map(w=>`<tr><td>${esc(w.id)}</td><td><b>${esc(w.name)}</b></td><td>${esc(w.section)}</td><td>${badge(w.role)}</td></tr>`))}</div>`;
if(page==='Shift logs')html=`<div class="panel">${table(['Reference','Section','Shift','Handover notes','Recorded'],data.logs.map(l=>`<tr><td>${esc(l.id)}</td><td>${esc(l.section)}</td><td>${esc(l.shift)}</td><td>${esc(l.notes)}</td><td>${esc(l.date)}</td></tr>`))}</div>`;
if(page==='Anonymous reports')html=`<div class="panel"><h2>Report a concern</h2><p>This prototype asks for no name. Reports remain visible in this browser to anyone who uses it. Secure anonymous submission, restricted review, and private follow-up require the server-backed version.</p>${table(['Reference','Section','Category','Concern'],data.reports.map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(r.section)}</td><td>${esc(r.category)}</td><td>${esc(r.notes)}</td></tr>`))}</div>`;
if(page==='Training')html=`<div class="sections">${data.training.map(t=>`<div class="panel training"><span class="muted">${esc(t.id)} · ${esc(t.section)}</span><h3>${esc(t.title)}</h3><p>Training register entry. Learning content and assessments will follow.</p><div class="progress"><i style="width:${t.status==='Complete'?100:0}%"></i></div><div class="row">${badge(t.status)}<button class="quiet" data-training="${esc(t.id)}">${t.status==='Complete'?'Reopen':'Mark complete'}</button></div></div>`).join('')}</div>`;
if(page==='Sections')html=sectionCards()+`<div class="panel" style="margin-top:24px"><h2>Expansion roadmap</h2><p>Electrical · Mechanical · Mining · Mine Support · Safety · Logistics · Laboratory</p><p class="muted">These departments are planned. The current pilot covers Mineral Processing only.</p></div>`;$('#content').innerHTML=html;if(page==='Fault reports'){updateFaults();$('#search').oninput=updateFaults;$('#filter').onchange=updateFaults}}
function sectionCards(){return `<div class="sections">${sections.map((s,i)=>`<div class="section-card"><span class="number">PROCESSING / 0${i+1}</span><h3>${s}</h3><p>${['Size reduction and feed preparation','Mineral separation and recovery','Dewatering and product handling'][i]}</p><div class="line"><i></i></div><div class="row"><span class="muted">Open faults</span><b>${data.faults.filter(f=>f.section===s&&f.status!=='Resolved').length}</b></div><div class="row"><span class="muted">Workers registered</span><b>${data.workers.filter(w=>w.section===s).length}</b></div></div>`).join('')}</div>`}
function updateFaults(){const q=$('#search').value.toLowerCase(),s=$('#filter').value;$('#fault-table').innerHTML=table(['Issue','Section','Priority','Support team','Status'],faultRows(data.faults.filter(f=>(s==='All sections'||s===f.section)&&JSON.stringify(f).toLowerCase().includes(q))))}
document.addEventListener('click',e=>{const p=e.target.closest('[data-page]');if(p){page=p.dataset.page;render()}const t=e.target.closest('[data-training]');if(t){const entry=data.training.find(x=>x.id===t.dataset.training);entry.status=entry.status==='Complete'?'Pending':'Complete';save()}});document.addEventListener('change',e=>{if(e.target.dataset.fault){data.faults.find(f=>f.id===e.target.dataset.fault).status=e.target.value;save()}});
let kind;const field=(name,label,options)=>`<label class="field">${label}${Array.isArray(options)?`<select name="${name}">${options.map(x=>`<option>${esc(x)}</option>`).join('')}</select>`:options==='textarea'?`<textarea required maxlength="2000" name="${name}"></textarea>`:`<input required maxlength="160" name="${name}">`}</label>`;
$('#add').onclick=()=>{kind=({'Overview':'faults','Fault reports':'faults',Workers:'workers','Shift logs':'logs','Anonymous reports':'reports',Training:'training'})[page];$('#form').reset();$('#form-title').textContent=$('#add').textContent.slice(2);let fields=field('section','Section',sections);if(kind==='faults')fields=field('title','Equipment / fault description')+fields+field('priority','Priority',['Low','Medium','High','Critical'])+field('team','Assign support team',['Mechanical','Electrical','Safety','Mineral Processing']);if(kind==='workers')fields=field('name','Worker name')+fields+field('role','Role',['Operator','Supervisor','Technician','Trainer','Manager']);if(kind==='logs')fields+=field('shift','Shift',['Day','Night'])+field('notes','Handover notes','textarea');if(kind==='reports')fields+=field('category','Concern category',['Safety','Equipment','Workplace concern','Other'])+field('notes','Concern (omit identifying information)','textarea');if(kind==='training')fields=field('title','Training title')+fields;$('#fields').innerHTML=fields;$('#form-note').textContent=kind==='reports'?'Demo only. This browser is not a secure anonymous reporting channel.':'Saved on this device for pilot review.';document.querySelector('dialog').showModal()};$('#close').onclick=()=>document.querySelector('dialog').close();$('#form').onsubmit=e=>{e.preventDefault();const record=Object.fromEntries(new FormData(e.target));if(Object.values(record).some(v=>!v.trim()))return;record.id=({faults:'FLT',workers:'EMP',logs:'LOG',reports:'RPT',training:'TR'})[kind]+'-'+crypto.randomUUID().slice(0,8).toUpperCase();record.date=new Date().toLocaleString('en-GB',{timeZone:'Africa/Harare'});if(kind==='faults')record.status='Open';if(kind==='training')record.status='Pending';data[kind].unshift(record);document.querySelector('dialog').close();save();if(kind==='reports')toast('Report reference: '+record.id)};render();
